import Foundation
import SwiftProtobuf

/// Typed access to the backend's protobuf RPC methods.
///
/// The message types (Anki_Decks_Deck etc) are generated by protoc-gen-swift
/// from proto/ (ios/gen-swift-protos.sh), and a typed method for each RPC is
/// generated into out/ios/generated/BackendServices.swift by
/// rslib/proto/swift.rs, eg:
///
///     let deck = try await backend.getDeck(.with { $0.did = deckId })
extension AnkiBackend {
    /// Encode `input`, call the method, and decode the output as `Output`.
    func rpcMessage<Input: SwiftProtobuf.Message, Output: SwiftProtobuf.Message>(
        service: UInt32,
        method: UInt32,
        _ input: Input,
        as _: Output.Type
    ) async throws -> Output {
        let output = try await rpc(service: service, method: method, input: input.serializedData())
        do {
            return try Output(serializedBytes: output)
        } catch {
            throw BackendError(kind: "PROTO_ERROR", message: "Invalid response from backend: \(error)")
        }
    }

    /// Call a method by the name used by the web pages (/_anki/<name>).
    /// Methods of FrontendService are not implemented by the backend, and
    /// fail with NOT_FOUND_ERROR here.
    func rpc(named name: String, input: Data) async throws -> Data {
        guard let index = BackendMethods.byName[name],
              !BackendMethods.frontendMethods.contains(name)
        else {
            throw BackendError(kind: "NOT_FOUND_ERROR", message: "Unknown backend method: \(name)")
        }
        return try await rpc(service: index.service, method: index.method, input: input)
    }
}
